import copy,http.server,json,os,pathlib,shutil,socket,subprocess,tempfile,threading,time,urllib.error,urllib.request

def free_port():
 with socket.socket() as endpoint:endpoint.bind(('127.0.0.1',0));return endpoint.getsockname()[1]

def request(base,path,method='GET',body=None,headers=None):
 req=urllib.request.Request(base+path,data=body,method=method,headers=headers or {})
 opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
 try:
  with opener.open(req,timeout=3) as response:return response.status,response.read(),dict(response.headers)
 except urllib.error.HTTPError as response:
  try:return response.code,response.read(),dict(response.headers)
  finally:response.close()

class Upstream:
 def __init__(self,status=200):self.status=status;self.requests=[];self.lock=threading.Lock()
 def __enter__(self):
  owner=self
  class Handler(http.server.BaseHTTPRequestHandler):
   protocol_version='HTTP/1.1'
   def log_message(self,*args):pass
   def respond(self):
    raw=self.rfile.read(int(self.headers.get('Content-Length',0)))
    with owner.lock:owner.requests.append({'method':self.command,'path':self.path,'body':raw.decode('utf8'),'headers':dict(self.headers)});index=len(owner.requests)
    status=owner.status(self.command,self.path,index) if callable(owner.status) else owner.status
    body=json.dumps({'method':self.command,'path':self.path,'attempt':index}).encode()
    self.send_response(status);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(body)));self.end_headers()
    try:self.wfile.write(body);self.wfile.flush()
    except (BrokenPipeError,ConnectionResetError):pass
   do_GET=do_POST=do_PUT=respond
  self.server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler);self.port=self.server.server_port
  self.thread=threading.Thread(target=lambda:self.server.serve_forever(poll_interval=.02),daemon=True);self.thread.start();return self
 def __exit__(self,*args):self.server.shutdown();self.server.server_close();self.thread.join(2)

