class Envoy:
 def __init__(self,config):self.config=copy.deepcopy(config);self.process=None;self.temp=None;self.log=None
 def __enter__(self):
  binary=shutil.which('envoy')
  if not binary:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: standalone Envoy missing')
  version=subprocess.run([binary,'--version'],capture_output=True,text=True,timeout=3)
  if version.returncode or '/1.36.13/' not in version.stdout+version.stderr:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: Envoy1.36.13 required')
  self.temp=tempfile.TemporaryDirectory(prefix='of-envoy-');self.root=pathlib.Path(self.temp.name);port=free_port();admin=free_port()
  while admin==port:admin=free_port()
  self.config['static_resources']['listeners'][0]['address']['socket_address']['port_value']=port
  self.config['admin']['address']['socket_address']['port_value']=admin
  self.base='http://127.0.0.1:'+str(port);self.admin='http://127.0.0.1:'+str(admin)
  path=self.root/'bootstrap.json';path.write_text(json.dumps(self.config),encoding='utf8');self.log=(self.root/'envoy.log').open('wb')
  try:
   self.process=subprocess.Popen([binary,'--config-path',str(path),'--disable-hot-restart','--concurrency','1','--log-level','error'],cwd=self.root,stdout=self.log,stderr=self.log)
   deadline=time.monotonic()+5
   while time.monotonic()<deadline:
    if self.process.poll() is not None:raise RuntimeError('Envoy startup failed: '+(self.root/'envoy.log').read_text(errors='replace')[-2400:])
    try:
     if request(self.admin,'/ready')[0]==200:break
    except (OSError,urllib.error.URLError):pass
    time.sleep(.02)
   else:raise RuntimeError('Envoy private readiness deadline')
   print('NATIVE_ENVOY_READY:1.36.13',flush=True);return self
  except BaseException:self.__exit__(None,None,None);raise
 def request(self,path,method='GET',body=None,headers=None):return request(self.base,path,method,body,headers)
 def stats(self):return {r['name']:r['value'] for r in json.loads(request(self.admin,'/stats?format=json')[1])['stats'] if 'name' in r and 'value' in r}
 def __exit__(self,*args):
  if self.process is not None:
   if self.process.poll() is None:self.process.terminate()
   try:self.process.wait(timeout=3)
   except subprocess.TimeoutExpired:self.process.kill();self.process.wait(timeout=2)
  if self.log:self.log.close()
  if self.temp:self.temp.cleanup()

